public String reverse(String str) {
    if (str == null) {
        return null;
    }
    int strLen = str.length();
    if (strLen == 0) {
        return "";
    }
    char[] outChars = str.toCharArray();
    int outPos = outChars.length - 1;
    for (int inPos = 0; inPos < strLen; inPos++) {
        outChars[outPos--] = str.charAt(inPos);
    }
    return new String(outChars);
}

