public static String base64Decode(final String s) {
  if (!s.matches("^[A-Za-z0-9+/=]*$")) {
    throw new IllegalArgumentException("Invalid input. The input should only contain characters from the Base64 regular.");
  }

  if (s.length() % 4 != 0) {
    throw new IllegalArgumentException("Invalid input. The input should be a multiple of 4 characters.");
  }

  int paddingChar = 0;
  if (s.charAt(s.length() - 1) == '=') {
    paddingChar++;
    if (s.charAt(s.length() - 2) == '=') {
      paddingChar++;
    }
  }

  byte[] decodedBytes = new byte[3 * s.length() / 4 - paddingChar];
  for (int i = 0, j = 0; i < s.length(); i += 4) {
    int byte0 = base64DecodeChar(s.charAt(i));
    int byte1 = base64DecodeChar(s.charAt(i + 1));
    int byte2 = base64DecodeChar(s.charAt(i + 2));
    int byte3 = base64DecodeChar(s.charAt(i + 3));
    decodedBytes[j] = (byte) (byte0 << 2 | (byte1 >> 4 & 0b11110000) >>> 4);
    if (j < decodedBytes.length - 1) {
      decodedBytes[j + 1] = (byte) (byte1 << 4 | (byte2 >> 2 & 0b11111100) >>> 2);
    }
    if (j < decodedBytes.length - 2) {
      decodedBytes[j + 2] = (byte) (byte2 << 6 | byte3);
    }
    j += 3;
  }

  String decodedString = new String(decodedBytes, StandardCharsets.UTF_8);
  decodedString = decodedString.substring(0, decodedString.length() - paddingChar);
  return decodedString;
}

