public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null || byteOffset < 0 || byteLength < 0) {
        throw new IllegalArgumentException("Invalid input");
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new ArrayIndexOutOfBoundsException("The specified range is out of bounds");
    }
    if (this.size + byteLength > this.capacity) {
        this.enlargeBuffer(byteLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.size, byteLength);
    this.size += byteLength;
    return this;
}

