    // Check if the input is valid
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Find the bucket with label 0
    int bucket0Index = -1;
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (labels.get(i) == 0) {
            bucket0Index = i;
            break;
        }
    }

    // Check if the bucket with label 0 exists
    if (bucket0Index == -1) {
        throw new IllegalArgumentException("Bucket with label 0 does not exist");
    }

    // Find the bucket with minimum label
