    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (labels.get(i) == minLabel) {
            minLabelIndex = i;
            break;
        }
    }

    // Check if the bucket with minimum label exists
    if (minLabelIndex == -1) {
        throw new IllegalArgumentException("Bucket with minimum label does not exist");
    }

    // Move all vertices from the bucket with minimum label to the bucket with label 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabelIndex);
    Set<Integer> bucket0 = bucketsByLabel.get(bucket0Index);
    bucket0.addAll(minLabelBucket);
    minLabelBucket.clear();

    // Update the labels accordingly
    labels.set(minLabelIndex, 0);
    labels.set(bucket0Index, minLabel);
}

