private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or the set of vertices is empty
    if (graph == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph is a multi-graph
    if (!graph.isMultigraph()) {
        return false;
    }

    // Check if all vertices are connected by undirected edges
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.hasEdgeConnecting(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

