private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Decode the first byte of the octet sequence
    // and validate that it is a valid UTF-8 octet
    int b = (int) bb.get(i) & 0xFF;
    if (b < 0xC0 || b > 0xF7 || (b & 0xE0) == 0xC0) {
        throw new IllegalArgumentException("Invalid UTF-8 octet at index " + i);
    }

    if (b < 0xC0) {
        // One-byte sequence (0xc0 ~ 0xff)
        sb.append((char) b);
        return i + 1;
    } else if (b < 0xE0) {
        // Two-byte sequence (0xc2 ~ 0xdf)
        int c = (int) bb.get(i + 1) & 0xFF;
        if (c < 0x80 || c > 0xBF || (c & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 octet sequence at index " + i);
        }
        sb.append((char) ((b & 0x1F) << 6 | c & 0x3F));
        return i + 2;
    } else if (b < 0xF0) {
        // Three-byte sequence (0xe0 ~ 0xef)
        int c1 = (int) bb.get(i + 1) & 0xFF;
        int c2 = (int) bb.get(i + 2) & 0xFF;
        if (c1 < 0x80 || c1 > 0xBF || (c1 & 0xC0) != 0x80 || c2 < 0x80 || c2 > 0xBF || (c2 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 octet sequence at index " + i);
        }
        sb.append((char) ((b & 0x0F) << 12 | (c1 & 0x3F) << 6 | c2 & 0x3F));
        return i + 3;
    } else {
        // Four-byte sequence (0xf0 ~ 0xf7)
        int c1 = (int) bb.get(i + 1) & 0xFF;
        int c2 = (int) bb.get(i + 2) & 0xFF;
        int c3 = (int) bb.get(i + 3) & 0xFF;
        if (c1 < 0x80 || c1 > 0xBF || (c1 & 0xC0) != 0x80 || c2 < 0x80 || c2 > 0xBF || (c2 & 0xC0) != 0x80 || c3 < 0x80 || c3 > 0xBF || (c3 & 0xC0) != 0x80) {
