public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Create a list to store the path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get the path component of the URI
    String path = u.getPath();

    // If the path component is null or empty, return an empty list
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    // Remove any leading '/' character from the path if it is an
    // absolute path component
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Split the path into individual path segments using '/' as the delimiter
    String[] segments = path.split("/");

    // Add each path segment to the list
    for (String segment : segments) {
        // If the decode parameter is true, decode the path segment
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
        }

        // Add the decoded path segment to the list
        pathSegments.add(new Path(segment));
    }

    // Return the list of path segments
    return pathSegments;
}

