public static String encodeTemplateNames(String s) {
    // Define a regex pattern to match the template parameter names
    Pattern templateParamPattern = Pattern.compile("\\{.*?\\}");
    // Define a matcher to find the template parameter names
    Matcher matcher = templateParamPattern.matcher(s);
    // Initialize an empty string builder to store the encoded string
    StringBuilder encodedStringBuilder = new StringBuilder();
    // Iterate over each match of the matcher and encode the template parameter names
    while (matcher.find()) {
        String templateParam = matcher.group();
        encodedStringBuilder.append(URLEncoder.encode(templateParam, "UTF-8"));
    }
    // Replace all occurrences of the escaped curly braces with percent-encoded '{' and '}'
    encodedStringBuilder.replace(0, encodedStringBuilder.length(), encodedStringBuilder.toString().replace("\\{", "%7B").replace("\\}", "%7D"));
    return encodedStringBuilder.toString();
}

