public String format(LoggingEvent event) {
    StringBuilder sb = new StringBuilder();
    String conversionPattern = event.getConversionPattern();
    for (int i = 0; i < conversionPattern.length(); i++) {
        char c = conversionPattern.charAt(i);
        if (c == '%') {
            char nextChar = conversionPattern.charAt(i + 1);
            switch (nextChar) {
                case 'n':
                    sb.append(System.lineSeparator());
                    break;
                case 'l':
                    sb.append(event.getLoggerName());
                    break;
                case 'p':
                    sb.append(event.getPriority());
                    break;
                case 't':
                    sb.append(event.getThreadName());
                    break;
                case 'm':
                    sb.append(event.getRenderedMessage());
                    break;
                case 'c':
                    sb.append(event.getClassName());
                    break;
                case 'x':
                    sb.append(event.getException());
                    break;
                default:
                    sb.append(nextChar);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

