public Mappings diffStructure(String tableName, Mappings mappings) {

    // Mappings for current index
    Mappings currentMappings = Mappings.get(tableName);

    // Mappings for current index without source config
    Mappings sourceLessCurrentMappings = new Mappings(currentMappings);
    sourceLessCurrentMappings.removeSourceConfig();

    // Mappings with fields that do not exist in the input mappings
    Mappings nonExistingMappings = new Mappings();

    for (Mapping mapping : sourceLessCurrentMappings) {
        if (!mappings.hasField(mapping.getFieldName())) {
            nonExistingMappings.add(mapping);
        }
    }

    return nonExistingMappings;

}

