private void pop(final String descriptor) {
    // Pop as many abstract types from the output frame stack as described by the given descriptor
    if (descriptor.charAt(0) == 'L' || descriptor.charAt(0) == '[') {
        // If the descriptor is a type, pop it and its supertypes
        for (int i = 0; i < getSubTypes(descriptor).length; i++) {
            pop(getSubTypes(descriptor)[i]);
        }
    } else {
        // If the descriptor is a method, pop its argument types
        for (int i = 0; i < getArgTypes(descriptor).length; i++) {
            pop(getArgTypes(descriptor)[i]);
        }
    }
}

